            id = `user_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
            localStorage.setItem('ungana_respondent_id', id);
        }
        setRespondentId(id);
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleScaleChange = (key: string, value: number) => {
        setFormData(prev => ({...prev, [key]: value}));
    };

    const isFormComplete = useMemo(() => {
        if (!formData.professionalRole || !formData.yearsExperience || !formData.appExperience || !formData.deviceUsed || !formData.durationOfUse) return false;
        if (formData.deviceUsed === 'Other' && !formData.otherDevice) return false;
        if (susQuestions.some(q => formData[q.key] === 0)) return false;
        if (mauqQuestions.some(q => formData[q.key] === 0)) return false;
        if (satisfactionQuestions.some(q => formData[q.key] === 0)) return false;
        return true;
    }, [formData, susQuestions, mauqQuestions, satisfactionQuestions]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!isFormComplete) return;

        setIsSubmitting(true);
        setSubmitError(null);

        // Calculate Scores
        const susScoreRaw = 
            (formData.sus1 - 1) + (5 - formData.sus2) + (formData.sus3 - 1) + (5 - formData.sus4) + 
            (formData.sus5 - 1) + (5 - formData.sus6) + (formData.sus7 - 1) + (5 - formData.sus8) + 
            (formData.sus9 - 1) + (5 - formData.sus10);
        const susTotal = susScoreRaw * 2.5;

        // Construct payload
        const data = {
            _replyto: targetEmail, // This tells Formspree where to send if not pre-configured
            subject: `Ungana Medical Evaluation - ${respondentId}`,
            respondentId,
            consent,
            ...formData,
            susTotalScore: susTotal,
            submissionDate: new Date().toISOString()
        };

        try {
            const response = await fetch(FORM_ENDPOINT, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(data)
            });

            if (response.ok) {
                setIsSubmitted(true);
                onFeedbackSubmitted();
            } else {
                const errorData = await response.json();
                console.error("Form submission failed", errorData);
                setSubmitError("There was a problem submitting the form. Please try again.");
            }
        } catch (error) {
            console.error("Network error during submission", error);
            setSubmitError("Network error. Please check your connection and try again.");
        } finally {
            setIsSubmitting(false);
        }
    };

    if (isSubmitted) {
        return (
             <div className="h-screen w-screen flex items-center justify-center bg-gray-100 p-4">
