        .attr("x1", "0%")
        .attr("y1", "0%")
        .attr("x2", "100%")
        .attr("y2", "100%");

    gradient.append("stop").attr("offset", "0%").attr("stop-color", "#ffffff");
    gradient.append("stop").attr("offset", "100%").attr("stop-color", "#f1f5f9"); // Slate-100

