      .attr("marker-end", `url(#arrow-diagram-${componentId})`);

    // Link Labels Group
    const linkLabelGroup = g.append("g").attr("class", "link-labels").selectAll("g").data(links).join("g");

    // Pill background for link text
    linkLabelGroup.append("rect")
        .attr("rx", 10)
        .attr("ry", 10)
        .attr("fill", "white")
        .attr("fill-opacity", 0.9)
        .attr("stroke", "#e2e8f0")
        .attr("stroke-width", 1);

    linkLabelGroup.append("text")
      .text((d: any) => d.label)
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em")
      .attr("font-size", "11px")
      .attr("font-weight", "500")
      .attr("fill", "#475569") // Slate-600
      .attr("font-family", "sans-serif")
      .each(function(d: any) {
          // @ts-ignore
          const bbox = this.getBBox();
          d.width = bbox.width + 12;
          d.height = bbox.height + 6;
      });

    linkLabelGroup.select("rect")
        .attr("width", (d: any) => d.width)
        .attr("height", (d: any) => d.height)
        .attr("x", (d: any) => -d.width / 2)
        .attr("y", (d: any) => -d.height / 2);

    // Nodes Group
    const nodeGroup = g.append("g").attr("class", "nodes").selectAll("g").data(nodes).join("g")
      .attr("cursor", "grab")
      .on("click", (event: any, d: any) => {
          event.stopPropagation();
          setSelectedElement(d);
      })
      .call(d3.drag()
        .on("start", (event: any, d: any) => {
            if (!event.active) simulationRef.current.alphaTarget(0.3).restart();
            d.fx = d.x;
            d.fy = d.y;
            d3.select(event.sourceEvent.target).attr('cursor', 'grabbing');
        })
        .on("drag", (event: any, d: any) => { d.fx = event.x; d.fy = event.y; })
        .on("end", (event: any, d: any) => {
            if (!event.active) simulationRef.current.alphaTarget(0);
            d.fx = null;
            d.fy = null;
            d3.select(event.sourceEvent.target).attr('cursor', 'grab');
        }));

    // Node Shape (Rounded Rect)
    nodeGroup.append("rect")
      .attr("rx", 10).attr("ry", 10)
      .attr("stroke", "#cbd5e1") // Slate-300
      .attr("stroke-width", 1.5)
      .attr("fill", `url(#node-gradient-${componentId})`)
      .style("filter", `url(#drop-shadow-${componentId})`);

    // Node Text
    nodeGroup.append("text")
      .text((d: any) => d.label)
      .attr("text-anchor", "middle")
      .attr("dy", ".35em")
      .attr("font-size", "13px")
      .attr("font-weight", "600")
      .attr("fill", "#1e293b") // Slate-800
      .each(function(d: any) {
           // @ts-ignore
           const bbox = this.getBBox();
           d.width = bbox.width + 24; // More padding
           d.height = bbox.height + 16;
      });

    // Resize rect to fit text
    nodeGroup.select("rect")
        .attr("width", (d: any) => d.width)
        .attr("height", (d: any) => d.height)
        .attr("x", (d: any) => -d.width / 2)
        .attr("y", (d: any) => -d.height / 2);

    simulationRef.current.force("collision").radius((d: any) => Math.max(d.width, d.height) / 2 + 20);
    simulationRef.current.alpha(1).restart();

    // Improved Zoom Behavior
    zoomRef.current = d3.zoom()
        .scaleExtent([0.1, 4])
        .on("zoom", (event: any) => g.attr("transform", event.transform));

    svg.call(zoomRef.current);
    svg.on("click", () => setSelectedElement(null));

    // Intersection Helper
    function intersectRect(rect: any, point: any) {
        const cx = rect.x;
        const cy = rect.y;
        const dx = point.x - cx;
        const dy = point.y - cy;
        const w = (rect.width || 0) / 2;
        const h = (rect.height || 0) / 2;

        if (w === 0 || h === 0) return { x: cx, y: cy }; 

        if (Math.abs(dy * w) < Math.abs(dx * h)) {
            if (dx > 0) return { x: cx + w, y: cy + dy * w / dx };
            else return { x: cx - w, y: cy - dy * w / dx };
        } else {
            if (dy > 0) return { x: cx + dx * h / dy, y: cy + h };
            else return { x: cx - dx * h / dy, y: cy - h };
        }
    }

    simulationRef.current.on("tick", () => {
